/** One dot per step of StoryTabs; the dot of the active step is filled. */
import { For, type JSX } from "solid-js";
import { Group } from "../primitives/group/group";
import { Inline } from "../primitives/inline/inline";
import { cn } from "../utils";
import type { Milestone } from "../blocks/milestone-timeline.types";
import type { StoryLabels } from "../blocks/story-tabs.types";

export type StoryDotsProps = {
  steps: Milestone[];
  active: string;
};

export function StoryDots({ steps, active }: StoryDotsProps) {
  return (
    <Group gap="2" align="center">
      <For each={steps ?? []}>{(s) => (
        <Inline
          class={cn("size-2 rounded-full", ((s.id === active) ? "bg-primary" : "bg-border"))}
          data-testid="story-dot"
        />
      )}</For>
    </Group>
  );
}
